// The Poreen loop around Ireland: geometry, stops, checkpoints and "where is someone who has run X km?".
// Data is generated by scripts/poreen/build-data.mjs.
import { ROUTE_LINE, ROUTE_KM, STOPS as RAW_STOPS, LAND } from './poreen-data.js';

/** Decode a Google encoded polyline into [lat, lng] pairs. */
export function decode(str, precision = 5) {
  const f = 10 ** precision;
  const out = [];
  let lat = 0;
  let lng = 0;
  let i = 0;
  const next = () => {
    let result = 0;
    let shift = 0;
    let b;
    do {
      b = str.charCodeAt(i++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);
    return result & 1 ? ~(result >> 1) : result >> 1;
  };
  while (i < str.length) {
    lat += next();
    lng += next();
    out.push([lat / f, lng / f]);
  }
  return out;
}

const rad = Math.PI / 180;
function km(a, b) {
  const dLat = (b[0] - a[0]) * rad;
  const dLng = (b[1] - a[1]) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a[0] * rad) * Math.cos(b[0] * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371.0088 * Math.asin(Math.sqrt(h));
}

/** Route vertices as [lat, lng]. */
export const LINE = decode(ROUTE_LINE, 5);
export const LOOP_KM = ROUTE_KM;

/** Cumulative km at each vertex, scaled so the simplified line matches the real road distance. */
const CUM = (() => {
  const c = new Float64Array(LINE.length);
  for (let i = 1; i < LINE.length; i++) c[i] = c[i - 1] + km(LINE[i - 1], LINE[i]);
  const scale = ROUTE_KM / c[c.length - 1];
  for (let i = 1; i < c.length; i++) c[i] *= scale;
  c[c.length - 1] = ROUTE_KM;
  return c;
})();

/** Every stop in running order: {name, at, lat, lng, cp?}. The last one is Dublin again, at LOOP_KM. */
export const STOPS = RAW_STOPS.map((s) => ({ name: s.name, at: CUM[s.i], lat: LINE[s.i][0], lng: LINE[s.i][1], cp: s.cp || null }));

/** Checkpoints (stamps): numbered from 1. The first is the start line, the last is the end of the lap. */
export const CHECKPOINTS = STOPS.filter((s) => s.cp).map((s, n) => ({ ...s, ...s.cp, n: n + 1, id: n + 1 }));

export const LAND_RINGS = {
  ireland: LAND.ireland.map((s) => decode(s, 4)),
  other: LAND.other.map((s) => decode(s, 4)),
};

function vertexAt(d) {
  // Last vertex whose cumulative distance is <= d.
  let lo = 0;
  let hi = CUM.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (CUM[mid] <= d) lo = mid;
    else hi = mid - 1;
  }
  return Math.min(lo, CUM.length - 2);
}

/** Where on the loop is someone who has run `total` km? */
export function locate(total) {
  total = Math.max(0, total || 0);
  const laps = Math.floor(total / LOOP_KM);
  const d = total - laps * LOOP_KM;
  const i = vertexAt(d);
  const a = LINE[i];
  const b = LINE[i + 1];
  const t = (d - CUM[i]) / (CUM[i + 1] - CUM[i] || 1);
  let s = 0;
  while (s < STOPS.length - 2 && STOPS[s + 1].at <= d) s++;
  const nextCp = CHECKPOINTS.find((c) => c.at > d) || CHECKPOINTS[CHECKPOINTS.length - 1];
  return {
    lat: a[0] + (b[0] - a[0]) * t,
    lng: a[1] + (b[1] - a[1]) * t,
    vertex: i,
    laps,
    lapKm: d,
    lapPct: d / LOOP_KM,
    prev: STOPS[s],
    next: STOPS[s + 1],
    toNext: STOPS[s + 1].at - d,
    nextCp,
    toNextCp: nextCp.at - d,
  };
}

/** Short description of a position, e.g. "past Kenmare, 12 km to Waterville". */
export function describe(total) {
  if (!total || total <= 0) return 'on the start line in Dublin';
  const p = locate(total);
  const lap = p.laps > 0 ? ` (lap ${p.laps + 1})` : '';
  if (p.lapKm - p.prev.at < 1.5) return `in ${p.prev.name}${lap}`;
  if (p.toNext < 1.5) return `nearly in ${p.next.name}${lap}`;
  return `past ${p.prev.name}, ${Math.round(p.toNext)} km to ${p.next.name}${lap}`;
}

/** Points of the loop between two distances (both within one lap, from <= to). */
export function slice(from, to) {
  from = Math.max(0, Math.min(from, LOOP_KM));
  to = Math.max(from, Math.min(to, LOOP_KM));
  const i = vertexAt(from);
  const j = vertexAt(to);
  const pa = locate(from);
  const pb = to >= LOOP_KM ? { lat: LINE[LINE.length - 1][0], lng: LINE[LINE.length - 1][1] } : locate(to);
  return [[pa.lat, pa.lng], ...LINE.slice(i + 1, j + 1), [pb.lat, pb.lng]];
}

/** The part of the current lap already covered by someone who has run `total` km. */
export const trail = (total) => slice(0, locate(total).lapKm);

/** Checkpoints passed for the first time between two running totals (handles laps). */
export function crossed(before, after) {
  const out = [];
  if (after <= before) return out;
  const firstLap = Math.floor(before / LOOP_KM);
  const lastLap = Math.floor(after / LOOP_KM);
  for (let lap = firstLap; lap <= lastLap; lap++) {
    for (const c of CHECKPOINTS) {
      // The start line counts as reached on your first km; later laps start where the last one ended.
      const at = lap * LOOP_KM + (c.n === 1 ? (lap === 0 ? 0.000001 : Infinity) : c.at);
      if (at > before && at <= after) out.push({ ...c, lap });
    }
  }
  return out;
}
